const data = $input.first().json;

// 1) Claude ka text dhoondo
let raw = '';
if (Array.isArray(data.content)) {
  raw = data.content
    .filter(c => typeof c.text === 'string')
    .map(c => c.text)
    .join('');
} else if (typeof data.text === 'string') {
  raw = data.text;
} else if (typeof data.output === 'string') {
  raw = data.output;
}
if (!raw) {
  throw new Error('Claude ka text nahi mila. Output ki keys: ' + Object.keys(data).join(', '));
}

// 2) Sirf { se } tak JSON nikalo
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('JSON nahi mila. Claude ka jawab: ' + raw.slice(0, 300));
}
const jsonText = raw.slice(start, end + 1);

// 3) Values ke andar asli line break ho to usay \n bana do
let fixed = '';
let inString = false;
let escaped = false;
for (const ch of jsonText) {
  if (inString) {
    if (escaped) { fixed += ch; escaped = false; }
    else if (ch === '\\') { fixed += ch; escaped = true; }
    else if (ch === '"') { fixed += ch; inString = false; }
    else if (ch === '\n') { fixed += '\\n'; }
    else if (ch === '\r') { }
    else if (ch === '\t') { fixed += ' '; }
    else { fixed += ch; }
  } else {
    if (ch === '"') inString = true;
    fixed += ch;
  }
}

let out;
try {
  out = JSON.parse(fixed);
} catch (e) {
  throw new Error('JSON parse fail: ' + e.message + ' | ' + fixed.slice(0, 300));
}

// 4) Video ke text ko box ke andar rakhne ke liye safety trim
const cut = (s, n) => {
  s = String(s || '').trim();
  if (s.length <= n) return s;
  return s.slice(0, n).replace(/\s+\S*$/, '').trim();
};
out.hook = cut(out.hook, 22);
out.detail_1 = cut(out.detail_1, 24);
out.detail_2 = cut(out.detail_2, 24);
out.product_name = cut(out.product_name, 30);
out.cta_text = cut(out.cta_text, 20);
out.price_text = String(out.price_text || '').trim();

return [{ json: out }];

